// Throwaway probe: what does readLoginURLActionFromTTY return when the
// controlling TTY hangs up (master closed) while waiting for a keypress?
func TestZZScratch_TTYHangupDuringRead(t *testing.T) {
	ptmx, tty, observer, _ := openLoginPromptPTY(t)
	defer observer.Close()

	type res struct {
		action loginURLAction
		err    error
	}
	ch := make(chan res, 1)
	var errBuf syncBuffer
	go func() {
		a, e := readLoginURLActionFromTTY(context.Background(), &errBuf, tty)
		ch <- res{a, e}
	}()

	time.Sleep(300 * time.Millisecond)
	_ = ptmx.Close() // hang up the master: reader sees EOF/EIO

	select {
	case r := <-ch:
		t.Logf("RESULT action=%v err=%v (err==nil: %v)", r.action, r.err, r.err == nil)
		t.Logf("STDERR: %q", errBuf.String())
	case <-time.After(3 * time.Second):
		t.Log("RESULT: Run() never returned after hangup (reader stayed blocked)")
	}
	_ = os.Stdout.Sync()
}

