	_ = ptmx.Close() // hang up the master
	time.Sleep(200 * time.Millisecond)
	cancel() // now cancel, as finishActionRead would

	select {
	case r := <-ch:
		t.Logf("RETURNED action=%v err=%v", r.action, r.err)
		t.Logf("STDERR: %q", errBuf.String())
	case <-time.After(3 * time.Second):
		t.Error("WEDGED: cancel did not unblock the reader after TTY hangup")
	}
}

